sysauto_script.script:
(function () {
    /**
     * Daily Overdue Maintenance Check
     * Scans all active transformers and fires an event for each
     * transformer whose next_maintenance_due date is today or in the past.
     * The event is consumed by an email notification to alert the assigned user.
     */
    var today = new GlideDate();
    var todayStr = today.getValue();

    var gr = new GlideRecord('x_2065243_transf_0_transformer');
    gr.addNotNullQuery('next_maintenance_due');
    gr.addQuery('next_maintenance_due', '<=', todayStr);
    gr.addQuery('operational_statu0', '!=', 'decommissioned');
    gr.query();

    var count = 0;
    while (gr.next()) {
        gs.eventQueue(
            'x_2065243_transf_0.maintenance.overdue',
            gr,
            gr.getValue('name') + ' (' + gr.getValue('number') + ')',
            gr.getValue('next_maintenance_due')
        );
        count++;
    }

    gs.info('Overdue Maintenance Check: Found ' + count + ' transformer(s) with overdue maintenance.');
})();
